-- public.worker_nowhere(p_world uuid, c creature)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.worker_nowhere(p_world uuid, c creature)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin
  if c.keeper is null then return; end if;
  if (select told_at from creature where world_id = p_world and id = c.id) > now() - interval '10 minutes'
    then return; end if;
  update creature set told_at = now() where world_id = p_world and id = c.id;
  perform wtell(p_world, c.keeper, c.name || ' holding '
    || lower(coalesce((select coalesce(name, c.carrying->>'def') from item_def where id = c.carrying->>'def'), 'a load'))
    || case when c.around is not null then ': storage in reach full.' else ': settlement storage full.' end, 'error');
end $function$
